#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;
    // prefixCount[b] = earlier prefixes (empty prefix included) whose parity mask has bit b set.
    long long prefixCount[26] = {}, parityCount[2] = {1, 0};
    long long totalOddLetters = 0, oddLengthSubstrings = 0, prefixIndex = 0;
    unsigned mask = 0;
    for (char ch : s) {
        mask ^= 1u << (ch - 'a');
        prefixIndex++;
        // Odd letters of substring (j, i] = popcount(mask_i XOR mask_j), summed bit by bit.
        for (int bit = 0; bit < 26; bit++)
            totalOddLetters += (mask >> bit & 1) ? prefixIndex - prefixCount[bit] : prefixCount[bit];
        for (int bit = 0; bit < 26; bit++) prefixCount[bit] += mask >> bit & 1;
        int parity = prefixIndex & 1;
        oddLengthSubstrings += parityCount[1 - parity];
        parityCount[parity]++;
    }
    // Cost of one substring = floor(odd / 2), and odd has the parity of the substring length.
    cout << (totalOddLetters - oddLengthSubstrings) / 2 << '\n';
}

import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        // prefixCount[b] = earlier prefixes (empty prefix included) whose parity mask has bit b set.
        long[] prefixCount = new long[26], parityCount = {1, 0};
        long totalOddLetters = 0, oddLengthSubstrings = 0, prefixIndex = 0;
        int mask = 0;
        for (int i = 0; i < s.length(); i++) {
            mask ^= 1 << (s.charAt(i) - 'a');
            prefixIndex++;
            // Odd letters of substring (j, i] = popcount(mask_i XOR mask_j), summed bit by bit.
            for (int bit = 0; bit < 26; bit++)
                totalOddLetters += ((mask >> bit) & 1) != 0 ? prefixIndex - prefixCount[bit] : prefixCount[bit];
            for (int bit = 0; bit < 26; bit++) prefixCount[bit] += (mask >> bit) & 1;
            int parity = (int) (prefixIndex & 1);
            oddLengthSubstrings += parityCount[1 - parity];
            parityCount[parity]++;
        }
        // Cost of one substring = floor(odd / 2), and odd has the parity of the substring length.
        System.out.println((totalOddLetters - oddLengthSubstrings) / 2);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := nextToken()
	// prefixCount[b] = earlier prefixes (empty prefix included) whose parity mask has bit b set.
	var prefixCount [26]int64
	parityCount := [2]int64{1, 0}
	var totalOddLetters, oddLengthSubstrings, prefixIndex int64
	var mask uint32
	for i := 0; i < len(s); i++ {
		mask ^= 1 << (s[i] - 'a')
		prefixIndex++
		// Odd letters of substring (j, i] = popcount(mask_i XOR mask_j), summed bit by bit.
		for bit := 0; bit < 26; bit++ {
			if mask>>bit&1 == 1 {
				totalOddLetters += prefixIndex - prefixCount[bit]
			} else {
				totalOddLetters += prefixCount[bit]
			}
		}
		for bit := 0; bit < 26; bit++ {
			prefixCount[bit] += int64(mask >> bit & 1)
		}
		parity := prefixIndex & 1
		oddLengthSubstrings += parityCount[1-parity]
		parityCount[parity]++
	}
	// Cost of one substring = floor(odd / 2), and odd has the parity of the substring length.
	fmt.Println((totalOddLetters - oddLengthSubstrings) / 2)
}
